import{_ as e,c as p,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"57、【巽】 巽下巽上","description":"周易闡真 - 57、【巽】 巽下巽上","frontmatter":{"title":"57、【巽】 巽下巽上","description":"周易闡真 - 57、【巽】 巽下巽上"},"headers":[],"relativePath":"classics/chanzhen/058.md","filePath":"classics/chanzhen/058.md"}'),s={name:"classics/chanzhen/058.md"};function n(c,a,i,o,l,h){return t(),p("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：重巽以申命。剛巽乎中正而志行。柔皆順乎剛，是以小亨、利有攸往、利見大人。。</p></blockquote><h1 id="_57、【巽】-巽下巽上" tabindex="-1">57、【巽】 巽下巽上 <a class="header-anchor" href="#_57、【巽】-巽下巽上" aria-label="Permalink to “57、【巽】 巽下巽上”">​</a></h1><p>初六：進退，利武人之貞。</p><p>九二：巽在床下，用史巫紛若，吉，無咎。</p><p>九三：頻巽，吝。</p><p>六四：悔亡，田獲三品。</p><p>九五：貞吉，悔亡，無不利。無初有終。先庚三日，後庚三日，吉。</p><p>上九：巽在床下，喪其資斧，貞兇。</p><h2 id="孔易闡真-​" tabindex="-1">孔易闡真 ​ <a class="header-anchor" href="#孔易闡真-​" aria-label="Permalink to “孔易闡真 ​”">​</a></h2><p>大象：隨風，巽。君子以申命行事。</p><p>巽者，漸入也，其象為風。上巽風，下巽風，是此風先起，彼風隨後，以風隨風，巽進之象也。</p><p>君子有見於此，知修道者與人同處，不能無事，既有事不能無行，凡行事須當從容不迫；倘行事急遽，而不與同事者預先申明其所以然，則人不我隨，行事不成。以是先申命而後行事焉。申者，申明也；命者，命告也；事者，如修德立業、積功累行、苦己利人之類，凡人所當行者皆是也。命不必拘，為上者申命於下，凡尊長首事者，告示於卑下眾人，俱謂命。未行事而先申命，則眾人知其事在當行，一人倡前，眾人隨後，行事未有不成者。亦如風隨風，風風相續，並行而不相悖，此君子與人為善之道也。</p><h2 id="悟元子註解-​" tabindex="-1">悟元子註解 ​ <a class="header-anchor" href="#悟元子註解-​" aria-label="Permalink to “悟元子註解 ​”">​</a></h2><p>巽者，進入也，伏下也，柔順漸進之謂。巽即為風。卦體一陰伏於二陽之下，以柔道而行剛道，不急不緩，漸次而進，既內巽而又外巽，既下巽而又上巽，由近達遠，自卑登高，如風漸吹漸遠，漸吹漸高，無處不到，故謂巽。此柔巽進道之卦，承上豐卦而來。豐者，明動合一，曲直應物，潛躍隨心，性命由我不由天矣。</p><p>然明動合一之道，豈易成哉！苟非柔巽漸進之功不能。柔巽則耐久，漸進則能入，柔巽漸進，愈久愈力，工夫不缺，終必至於深造自得，是以巽小而有亨道也。但能巽雖是亨道，或知其巽而不能行其巽者有矣；或能巽下，不能巽上者有矣；或能巽上，不能巽下者有矣；或巽於順，不能巽於逆者有矣；或巽於始，不能巽於終者有矣。凡此皆不能實行巽進之道。巽而不通，求其知行兼能，剛柔並用，能上能下，能順能逆，能內能外，始終如一之巽，惟具中正之大人能之，是以利有攸往，利見大人也。</p><p>夫大人者，以性命為重，以道德為貴，視幻身如枯木，視富貴如浮雲，內常有餘，外若不足，真履實踐，漸次進步，心堅志遠，不到大道完成之後，絕不休歇，故利。若非大人，執於一偏，巽而不中不正，何能有往有利?此有往之利，必歸於大人耳。</p><p>初六，柔而無剛，逡畏不力，方進即退，終難深造。然大道人人有分，特患無志耳。果若有志，親近真師，叩求口訣，勇猛精進，如武人之貞，未有入道不利者。此柔而借剛之巽也。</p><p>九二，剛以柔用，不滿不盈，屈己下人，如巽在床下，用史巫紛若，不但治己得吉，而且應人亦無咎。此剛而能柔之巽也。</p><p>九三，自滿自盈，有己無人，不能虛心請益，由下而上巽，乃自用聰明，由上而上巽，本欲向前，反成落後，是謂頻巽。巽至於頻，順者能巽，逆者不巽，或巽或不巽，適以取吝而已。此剛而不能柔之巽也。</p><p>六四，獨柔無剛，似乎柔之太過，不能深造而有悔。然柔之得正，上近五剛，巽順於上，而得上之濟，是獲上之一品也。下近三剛，巽順於下，而得下之濟，是獲下之一品也。陰居陽中，順之逆之，皆不失其正，是獲中之一品也。上、中、下三品大藥，歸於中央，陰陽混合，金丹有象，純是生機，如田中種物，無有不告成者，有何悔之不亡乎?此柔而中正之巽也。</p><p>九五，剛而能巽，惟精推一，允執厥中，是以有悔可亡，而修道無不利矣。其利者，蓋以剛而能柔之大人，能下能上，始而巽以自下，似乎用柔傷剛，是無初也。既而巽進於上，反能借柔全剛，是有終也。無初有終之象，如月之先庚三日，後庚三日。先庚三日在於二十八，後庚在於初三。二十八微陽消於艮地，至三十光輝全隱。自二十八至三十，方三日，所謂“先庚三日”也。晦朔之半，月霑日光，陰中藏陽，至初三現蛾眉之光於庚方。自初一至初三，方三日，所謂“後庚三日”也。先庚三日，巽藏其陽；後庚三日，巽進其陽。金丹之道先巽下而深造用其柔，後巽上而自得全其剛。陰中含陽，陽中用陰，大小無傷，至中至正，金丹凝結，剛巽之利，其吉莫大焉。此剛柔兩用之巽也。</p><p>上九，在巽之終，巽下之功已畢，柔道宜退，剛道宜進，可以點化群陰之時，不必下巽，須當上巽，居於床上矣。若固執不通，宜在床上者，終在床下。柔過於剛，陰氣不化，必至大藥得而復失，前功俱廢，貞而有兇，可於理決之。此柔過於剛之巽也。</p><p>然則巽進漸入之道，須要識急緩、辨吉凶、知止足，可剛則剛，可柔則柔，隨時而用，巽進於剛柔中正為極功也。</p>',23)])])}const m=e(s,[["render",n]]);export{d as __pageData,m as default};
